import type { UserRole } from '../../api/models/user.model.js';
import { UserFactory } from '../factories/user.factory.js';
import { userDataSchema, type UserData } from '../schemas/test-data.schema.js';

/**
 * Fluent builder for readable test setup when a scenario cares about specific
 * fields:  new UserBuilder().named('Grace', 'Hopper').withRole('editor').build()
 * Unspecified fields are generated by UserFactory.
 */
export class UserBuilder {
  private data: UserData = UserFactory.build();

  named(firstName: string, lastName: string): this {
    this.data = { ...this.data, firstName, lastName };
    return this;
  }

  withEmail(email: string): this {
    this.data = { ...this.data, email };
    return this;
  }

  withRole(role: UserRole): this {
    this.data = { ...this.data, role };
    return this;
  }

  /** Builds a validated user. */
  build(): UserData {
    return userDataSchema.parse(this.data);
  }

  /** Builds without validation – for negative tests that need deliberately invalid data. */
  buildUnchecked(mutate: (data: Record<string, unknown>) => void): Record<string, unknown> {
    const copy: Record<string, unknown> = { ...this.data };
    mutate(copy);
    return copy;
  }
}
